import "fmt"

func main() {
	var s1, s2 string
	fmt.Scan(&s1, &s2)

	if len(s1) != len(s2) {
		fmt.Println("NO")
		return
	}

	b := []byte(s2)
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}

	if s1 == string(b) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

