	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	var s1, s2 string
	if scanner.Scan() {
		s1 = scanner.Text()
	}
	if scanner.Scan() {
		s2 = scanner.Text()
	}

	if len(s1) != len(s2) {
		fmt.Println("NO")
		return
	}

	runes2 := []rune(s2)
	for i, j := 0, len(runes2)-1; i < j; i, j = i+1, j-1 {
		runes2[i], runes2[j] = runes2[j], runes2[i]
	}

	if s1 == string(runes2) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

