	"fmt"
)

func main() {
	var s1, s2 string
	fmt.Scan(&s1, &s2)
	l1 := len(s1)
	l2 := len(s2)
	c := 0
	for j, k := 0, l2-1; j < l1 && k >= 0; j, k = j+1, k-1 {
		if s1[j] == s2[k] {
			c++
		}
	}
	if l1 == c {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

